#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json, codecs
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, timedelta, timezone

FACTORS = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
           'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLUMNS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
WCOL = {'east': 'gross', 'lakeside': 'gross_kg', 'harbor': 'weight', 'river': 'weight', 'west': 'weight'}
DCOL = {'east': 'shipped', 'lakeside': 'shipped', 'harbor': 'date', 'river': 'shipped', 'west': 'shipped'}
SCOL = {'east': 'status', 'lakeside': 'status', 'harbor': 'state', 'river': 'status', 'west': 'status'}
TCOL = {'east': 'type', 'lakeside': 'kind', 'harbor': 'rec', 'river': 't', 'west': 'typ'}
IDCOL = {'east': 'id', 'lakeside': 'id', 'harbor': 'ref', 'river': 'ref', 'west': 'id'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'harbor': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
CODES = {'DLV': 'delivered', 'DLL': 'delivered_late', 'D': 'delivered', 'L': 'delivered_late'}
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16')
    enc = 'utf-8'
    head = b[:4096].decode('latin-1')
    for line in head.split('\n')[:20]:
        m = re.match(r'#\s*charset\s*:\s*(\S+)', line)
        if m:
            try:
                enc = codecs.lookup(m.group(1)).name
            except LookupError:
                pass
            break
    return b.decode(enc)


def parse_id(s):
    m = re.match(r'^\s*SH\D*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    s = (s or '').strip()
    if s.upper() in CODES:
        return CODES[s.upper()]
    return re.sub(r'[\s\-]+', '_', s.lower())


def counted(s):
    return s in ('delivered', 'delivered_late')


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'V'
    if s.startswith('c') or s.startswith('a'):
        return 'C'
    return 'N'


def parse_date(v, form=None):
    v = v.strip()
    if 'T' in v or (' ' in v and ':' in v):
        return parse_dt(v)
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$', v)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    f = (form or '').strip().upper()
    if f == 'SERIAL':
        return date(1899, 12, 30) + timedelta(days=int(float(v)))
    if re.fullmatch(r'\d{7}', v):
        return date(int(v[:4]), 1, 1) + timedelta(days=int(v[4:]) - 1)
    if re.fullmatch(r'\d{8}', v) and not re.search(r'[^\d]', v) and f in ('', 'YYYYMMDD', 'ISO', 'YMD'):
        return date(int(v[:4]), int(v[4:6]), int(v[6:]))
    parts = re.split(r'\D+', v)
    parts = [p for p in parts if p]
    if len(parts) != 3:
        raise ValueError('date ' + v)
    a, b, c = [int(p) for p in parts]
    if f in ('', 'ISO', 'YMD', 'YYYY-MM-DD', 'YYYYMMDD') or f.startswith('Y'):
        return date(a, b, c)
    if f.startswith('M'):
        return date(c, a, b)
    if f.startswith('D'):
        return date(c, b, a)
    return date(a, b, c)


def parse_dt(v):
    v = v.strip()
    if v.endswith('Z') or v.endswith('z'):
        v = v[:-1] + '+00:00'
    d = datetime.fromisoformat(v)
    if d.tzinfo is not None:
        d = d.astimezone(timezone.utc)
    return d.date()


def dec(s, group):
    s = s.strip()
    if group == '.':
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def weight_kg(text, unit_chain, group=','):
    """text may carry a unit suffix; unit_chain: list of fallback units in priority order."""
    text = text.strip()
    m = re.match(r'^([-+0-9.,]+)\s*([A-Za-z]+)$', text)
    unit = None
    if m and m.group(2).lower() in FACTORS:
        text, unit = m.group(1), m.group(2).lower()
    if unit is None:
        for u in unit_chain:
            if u:
                unit = u
                break
    if unit is None:
        unit = 'kg'
    return dec(text, group) * FACTORS[unit]


def unit_word(s):
    m = re.match(r'\s*([A-Za-z]+)', s or '')
    if m and m.group(1).lower() in FACTORS:
        return m.group(1).lower()
    return None


def suffix_unit(name):
    m = re.search(r'_(kg|g|lb|oz)$', name.lower())
    return m.group(1) if m else None


class Rec:
    __slots__ = ('num', 'type', 'month', 'kg', 'counted')

    def __init__(self, num, t, month=None, kg=None, c=False):
        self.num, self.type, self.month, self.kg, self.counted = num, t, month, kg, c


def safe_rec(num, t, fn):
    if t == 'V':
        return Rec(num, t)
    month, kg, c = fn()
    return Rec(num, t, month, kg, c)


def read_delimited(depot, text):
    delim = DELIM[depot]
    cols = set(COLUMNS[depot])
    seq = None
    recs = []
    dirs = {}
    header = None
    if delim == ',':
        rows = csv.reader(io.StringIO(text, newline=''), delimiter=',', quotechar='"')
    else:
        rows = (ln.rstrip('\r').split(delim) for ln in text.split('\n'))
    for r in rows:
        if not r or (len(r) == 1 and not r[0].strip()):
            continue
        if r[0].startswith('#'):
            line = ','.join(r) if delim == ',' else delim.join(r)
            m = re.match(r'^#\s*([^:=]+?)\s*:\s*(.*?)\s*$', line)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).lower())
                dirs[name] = m.group(2)
                if name == 'seq' and seq is None:
                    seq = int(m.group(2))
            else:
                m = re.search(r'\bseq\s*=\s*(\d+)', line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        low = [x.strip().lower() for x in r]
        if all(x in cols for x in low) and len(set(low)) == len(low):
            header = low
            continue
        if header is None:
            continue
        n = len(header)
        wi = header.index(WCOL[depot])
        row_unit = None
        if len(r) == n + 1:
            row_unit = unit_word(r[wi + 1])
            r = r[:wi + 1] + r[wi + 2:]
        if len(r) < n:
            r = r + [''] * (n - len(r))
        d = dict(zip(header, r))
        num = parse_id(d.get(IDCOL[depot], ''))
        if num is None:
            continue
        t = rtype(d.get(TCOL[depot], ''))
        form = None
        wunit = None
        for k, v in dirs.items():
            if 'date' in k:
                form = v
            elif 'unit' in k:
                wunit = unit_word(v)

        def fn(d=d, form=form, wunit=wunit, row_unit=row_unit):
            ds = d[DCOL[depot]]
            dt = parse_date(ds, form or BASE_DATE[depot])
            wname = WCOL[depot]
            group = '.' if depot == 'west' else ','
            kg = weight_kg(d[wname], [suffix_unit(wname), row_unit, wunit], group)
            return (dt.year, dt.month), kg, counted(norm_status(d[SCOL[depot]]))
        recs.append(safe_rec(num, t, fn))
    return seq, recs


FW = {
    'FW1': (42, dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)), 'g', 'ydoy'),
    'FW2': (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)), 'cg', 'ymd'),
    'FW3': (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)), 'dlb', 'ydoy'),
}


def read_south(text):
    seq = None
    layout = None
    recs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\S+)', line)
            if m:
                layout = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if '\x0c' in line or not line.strip():
            continue
        if re.search(r'LISTING.*PAGE', line):
            continue
        lay = None
        for k, v in FW.items():
            if v[0] == len(line):
                lay = k
        if lay is None:
            lay = layout
            if lay not in FW:
                continue
            line = line.ljust(FW[lay][0])
        _, f, wk, dk = FW[lay]
        g = {k: line[a:b] for k, (a, b) in f.items()}
        num = parse_id(g['id'])
        if num is None:
            continue
        t = rtype(g['type'])

        def fn(g=g, lay=lay, wk=wk, dk=dk):
            s = g['shipped']
            if dk == 'ydoy':
                dt = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
            else:
                dt = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
            w = Decimal(int(g['weight']))
            if lay == 'FW1':
                kg = w * FACTORS['g']
            elif lay == 'FW2':
                kg = w / 100
            else:
                kg = w / 10 * FACTORS['lb']
            return (dt.year, dt.month), kg, counted(norm_status(g['status']))
        recs.append(safe_rec(num, t, fn))
    return seq, recs


def read_north(text):
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = parse_id(str(o.get('id', '')))
            if num is None:
                continue
            t = rtype(o.get('kind'))

            def fn(o=o):
                dt = parse_dt(o['shipped_at']) if 'T' in str(o['shipped_at']) else parse_date(str(o['shipped_at']))
                wk = [k for k in o if k.startswith('weight_')]
                k = wk[0]
                kg = Decimal(str(o[k])) * FACTORS[k[7:].lower()]
                return (dt.year, dt.month), kg, counted(norm_status(str(o.get('status', ''))))
            recs.append(safe_rec(num, t, fn))
    return seq, recs


def read_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = unit_word(root.get('weight-unit'))
    rform = root.get('dates') or root.get('date-format')
    recs = []
    for el in root.iter('shipment'):
        num = parse_id(el.get('id', ''))
        if num is None:
            continue
        t = rtype(el.get('type'))

        def fn(el=el):
            sh = el.find('shipped')
            s = sh.text if sh is not None and sh.text else el.get('shipped')
            dt = parse_date(s, rform)
            w = el.find('weight')
            u = unit_word(w.get('unit')) if w.get('unit') else None
            kg = weight_kg(w.text, [u, runit])
            st = el.find('status')
            return (dt.year, dt.month), kg, counted(norm_status(st.text if st is not None else el.get('status')))
        recs.append(safe_rec(num, t, fn))
    return seq, recs


def read_file(depot, path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if depot == 'central':
        return read_central(b)
    text = decode(b)
    if depot == 'south':
        return read_south(text)
    if depot == 'north':
        return read_north(text)
    return read_delimited(depot, text)


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.setdefault(name.split('-')[0], []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for p in paths:
            seq, recs = read_file(depot, p)
            exports.append((seq if seq is not None else -1, p, recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                if r.type == 'N':
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == 'C':
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    depots = {d: [0, Decimal(0)] for d in sorted(files)}
    months = {}
    handovers = 0
    for num, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        r = current[ds[0]][num]
        if r.counted:
            depots[ds[0]][0] += 1
            depots[ds[0]][1] += r.kg
            m = months.setdefault(r.month, [0, Decimal(0)])
            m[0] += 1
            m[1] += r.kg
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': v[0], 'total_kg': q(v[1])} for d, v in depots.items()},
        'months': {'%04d-%02d' % k: {'shipments': v[0], 'total_kg': q(v[1])} for k, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(out, f, indent=2)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
